console.log(comprimentoTres); // [ <3 empty items> ]

const aPartirDeString = Array.from("abc");
console.log(aPartirDeString); // ["a", "b", "c"]

const quadrados = Array.from({ length: 5 }, (_, indice) => indice ** 2);
console.log(quadrados); // [0, 1, 4, 9, 16]

const pilha = [1, 2];
const novoComprimento = pilha.push(3, 4);
console.log(pilha, novoComprimento); // [1,2,3,4] 4

const removidoDoFim = pilha.pop();
console.log(pilha, removidoDoFim); // [1,2,3] 4

const fila = [1, 2];
fila.unshift(-1, 0);
console.log(fila); // [-1, 0, 1, 2]

const removidoDoInicio = fila.shift();
console.log(fila, removidoDoInicio); // [0, 1, 2] -1

const letras = ["a", "b", "c", "d", "e"];

const copiaParcial = letras.slice(1, 3);
console.log(copiaParcial, letras);
// ["b","c"]  ["a","b","c","d","e"]  (original intacto)

const duasUltimas = letras.slice(-2);
console.log(duasUltimas); // ["d", "e"]

const removidos = letras.splice(1, 2, "x", "y", "z");
console.log(letras, removidos);
// letras agora é ["a","x","y","z","d","e"]
// removidos é ["b","c"]

const parte1 = ["a", "b"];
const parte2 = ["c", "d"];

const combinado = parte1.concat(parte2, "e");
console.log(combinado); // ["a","b","c","d","e"]
console.log(parte1, parte2); // ambos inalterados

const frase = combinado.join(" - ");
console.log(frase); // "a - b - c - d - e"

const letras = ["banana", "abacate", "cereja"];
letras.reverse();
console.log(letras); // ["cereja", "abacate", "banana"]

const numeros = [10, 1, 2, 21];

console.log(numeros.slice().sort());
// [1, 10, 2, 21]  <- armadilha: ordenação como texto

console.log(numeros.slice().sort((a, b) => a - b));
// [1, 2, 10, 21]  <- correto, ordem crescente

console.log(numeros.slice().sort((a, b) => b - a));
// [21, 10, 2, 1]  <- ordem decrescente

console.log(numeros); // [10, 1, 2, 21], original intacto (usámos slice() para copiar antes)

